package com.motionstudio.part2
object ParticleRenderer {enum class Mode{POINT,SPRITE,ADDITIVE,ALPHA};fun render(dst:FrameBuffer,particles:List<Particle>,mode:Mode=Mode.ALPHA,sprite:FrameBuffer?=null):FrameBuffer{val o=dst.copy();for(p in particles){if(sprite!=null&&(mode==Mode.SPRITE||mode==Mode.ADDITIVE)){drawSprite(o,p,sprite,mode==Mode.ADDITIVE)}else{val x=p.x.toInt();val y=p.y.toInt();if(x in 0 until o.width&&y in 0 until o.height){val c=Rgba(p.color.r,p.color.g,p.color.b,p.color.a*p.opacity);o.set(x,y,if(mode==Mode.ADDITIVE)BlendModes.blend(c,o.get(x,y),BlendMode.ADD)else BlendModes.blend(c,o.get(x,y),BlendMode.NORMAL))}}};return o}private fun drawSprite(o:FrameBuffer,p:Particle,s:FrameBuffer,add:Boolean){for(y in 0 until s.height)for(x in 0 until s.width){val dx=(p.x-s.width/2f+x).toInt();val dy=(p.y-s.height/2f+y).toInt();if(dx in 0 until o.width&&dy in 0 until o.height){val c=s.get(x,y);val pc=Rgba(c.r,c.g,c.b,c.a*p.opacity);o.set(dx,dy,BlendModes.blend(pc,o.get(dx,dy),if(add)BlendMode.ADD else BlendMode.NORMAL))}}}}
